# Varsayılan (fallback) ataması ve zenginleştirme uygula
for f in ALL_FOOTBALLERS:
    fname = f.get("name", "")
    
    # Zenginleştirme sözlüğünden özellikleri üzerine yaz
    if fname in FOOTBALLER_ENRICHMENTS:
        f.update(FOOTBALLER_ENRICHMENTS[fname])

    # Eksik kalan oyuncu varsa varsayılan pozisyon ata
    if "detailed_position" not in f:
        pos = f.get("position", "")
        if pos == "Forvet": f["detailed_position"] = "Santrafor"
        elif pos == "Orta Saha": f["detailed_position"] = "MOS"
        elif pos == "Defans": f["detailed_position"] = "Stoper"
        elif pos == "Kaleci": f["detailed_position"] = "Kaleci"

    # Kart üzerinde görünecek pozisyon yazısını detaylı ismiyle güncelle
    dp = f.get("detailed_position", "")
    if dp in DETAILED_POSITION_LABELS:
        f["position"] = DETAILED_POSITION_LABELS[dp]